// Process calendar events to extract recently completed sessions
const events = $input.all().map(item => item.json);

// Filter for coaching sessions that have ended in the last 2 hours
const now = new Date();
const twoHoursAgo = new Date(now.getTime() - 2 * 60 * 60 * 1000);
const thirtyMinutesAgo = new Date(now.getTime() - 30 * 60 * 1000);

const completedSessions = events.filter(event => {
  // Check if event has ended
  const endTime = new Date(event.end.dateTime || event.end.date);
  return endTime > twoHoursAgo && endTime < thirtyMinutesAgo;
});

// Extract client information from event details
const processedSessions = completedSessions.map(event => {
  // Extract client email from attendees
  const clientEmail = event.attendees ? 
    event.attendees.find(a => a.email !== event.organizer.email)?.email : 
    null;

  // Extract client name from summary or description
  let clientName = '';
  const summaryMatch = event.summary.match(/Session with (.+)/i);
  if (summaryMatch && summaryMatch[1]) {
    clientName = summaryMatch[1].trim();
  } else if (event.description) {
    const descMatch = event.description.match(/Client:\s*(.+?)(?:\n|$)/i);
    if (descMatch && descMatch[1]) {
      clientName = descMatch[1].trim();
    }
  }

  return {
    eventId: event.id,
    summary: event.summary,
    description: event.description || '',
    startTime: event.start.dateTime || event.start.date,
    endTime: event.end.dateTime || event.end.date,
    clientEmail: clientEmail,
    clientName: clientName,
    location: event.location || 'Online',
    status: event.status
  };
});

// Return the processed sessions
return {
  totalCompletedSessions: processedSessions.length,
  sessions: processedSessions
};

// Filter out sessions that already have feedback requests sent
const completedSessions = $node["Code - Process Completed Sessions"].json.sessions;
const feedbackLog = $node["Google Sheets - Get Feedback Log"].json;

// Create a set of event IDs that already have feedback requests
const processedEventIds = new Set();
feedbackLog.forEach(entry => {
  if (entry.event_id) {
    processedEventIds.add(entry.event_id);
  }
});

// Filter out sessions that already have feedback requests
const sessionsNeedingFeedback = completedSessions.filter(session => 
  !processedEventIds.has(session.eventId)
);

// Return the filtered sessions
return {
  totalSessionsNeedingFeedback: sessionsNeedingFeedback.length,
  sessions: sessionsNeedingFeedback
};

// Process each session individually
const sessions = $node["Code - Filter New Sessions"].json.sessions;
const currentIndex = $input.item.index;

if (currentIndex < sessions.length) {
  return sessions[currentIndex];
} else {
  return {};
}

// Match client data with session information
const session = $input.item.json;
const clientsData = $node["Google Sheets - Get Client Data"].json;

// Find client by email or name
let clientMatch = null;
if (session.clientEmail) {
  clientMatch = clientsData.find(client => 
    client.email && client.email.toLowerCase() === session.clientEmail.toLowerCase()
  );
}

// If no match by email, try by name
if (!clientMatch && session.clientName) {
  const clientNameLower = session.clientName.toLowerCase();
  clientMatch = clientsData.find(client => {
    const fullName = `${client.first_name || ''} ${client.last_name || ''}`.toLowerCase();
    return fullName.includes(clientNameLower) || clientNameLower.includes(fullName);
  });
}

// Prepare client data
let clientData = {};
if (clientMatch) {
  clientData = {
    clientId: clientMatch.id || clientMatch.client_id,
    firstName: clientMatch.first_name || clientMatch.firstName || '',
    lastName: clientMatch.last_name || clientMatch.lastName || '',
    email: clientMatch.email || session.clientEmail,
    phone: clientMatch.phone || '',
    coachingType: clientMatch.coaching_type || clientMatch.coachingType || 'General',
    sessionCount: parseInt(clientMatch.session_count || clientMatch.sessionCount || 0),
    notes: clientMatch.notes || '',
    status: clientMatch.status || 'Active',
    clientFound: true
  };
} else {
  // Create temporary client data if not found
  clientData = {
    clientId: `TEMP-${Date.now()}`,
    firstName: session.clientName ? session.clientName.split(' ')[0] : 'Client',
    lastName: session.clientName ? session.clientName.split(' ').slice(1).join(' ') : '',
    email: session.clientEmail || '',
    phone: '',
    coachingType: 'Unknown',
    sessionCount: 0,
    notes: 'Automatically created from calendar event',
    status: 'Pending',
    clientFound: false
  };
}

// Generate a unique feedback ID
const feedbackId = `FB-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

// Create feedback form URL (in a real implementation, this would be a Google Form or similar)
const feedbackFormUrl = `https://forms.example.com/feedback?id=${feedbackId}&client=${encodeURIComponent(clientData.clientId)}&session=${encodeURIComponent(session.eventId)}`;

// Combine session and client data
return {
  ...session,
  ...clientData,
  fullName: `${clientData.firstName} ${clientData.lastName}`.trim(),
  sessionDateTime: new Date(session.startTime).toLocaleString(),
  sessionDuration: calculateDuration(session.startTime, session.endTime),
  feedbackId,
  feedbackFormUrl
};

// Helper function to calculate duration
function calculateDuration(start, end) {
  const startTime = new Date(start);
  const endTime = new Date(end);
  const durationMs = endTime - startTime;
  const minutes = Math.floor(durationMs / 60000);
  return `${minutes} minutes`;
}

// Process feedback responses and status
const feedbackResponses = $node["Google Sheets - Check Feedback Responses"].json;
const feedbackStatus = $node["Google Sheets - Get Feedback Status"].json;

// Match responses with tracking data
const now = new Date();
const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
const threeDaysAgo = new Date(now.getTime() - 3 * 24 * 60 * 60 * 1000);

// Find new responses to update status
const newResponses = [];
feedbackResponses.forEach(response => {
  // Find matching tracking entry
  const trackingEntry = feedbackStatus.find(entry => 
    entry.feedback_id === response.feedback_id
  );

  if (trackingEntry && trackingEntry.feedback_received === 'No') {
    newResponses.push({
      ...response,
      trackingRow: feedbackStatus.indexOf(trackingEntry) + 2, // +2 for header row and 0-indexing
      clientName: trackingEntry.client_name,
      sessionDate: trackingEntry.session_date,
      overallRating: parseInt(response.overall_rating || response.rating || '0'),
      comments: response.comments || response.feedback || ''
    });
  }
});

// Find entries needing reminders
const needsReminder = [];
feedbackStatus.forEach(entry => {
  if (entry.feedback_received === 'No' && entry.reminder_sent === 'No') {
    // Check if session was 1-3 days ago
    const sessionDate = new Date(entry.session_date);
    if (sessionDate < oneDayAgo && sessionDate > threeDaysAgo) {
      needsReminder.push({
        ...entry,
        trackingRow: feedbackStatus.indexOf(entry) + 2 // +2 for header row and 0-indexing
      });
    }
  }
});

return {
  newResponsesCount: newResponses.length,
  newResponses,
  needsReminderCount: needsReminder.length,
  needsReminder
};

// Process each new feedback response
const newResponses = $node["Code - Process Feedback Status"].json.newResponses;
const currentIndex = $input.item.index;

if (currentIndex < newResponses.length) {
  return newResponses[currentIndex];
} else {
  return {};
}

// Process each entry needing a reminder
const needsReminder = $node["Code - Process Feedback Status"].json.needsReminder;
const currentIndex = $input.item.index;

if (currentIndex < needsReminder.length) {
  return needsReminder[currentIndex];
} else {
  return {};
}

// Prepare reminder email data
const reminderData = $input.item.json;
const clientsData = $node["Google Sheets - Get Client Data for Reminders"].json;

// Find client by ID or name
let clientMatch = null;
if (reminderData.client_id) {
  clientMatch = clientsData.find(client => 
    client.id === reminderData.client_id || client.client_id === reminderData.client_id
  );
}

// If no match by ID, try by name
if (!clientMatch && reminderData.client_name) {
  const clientNameLower = reminderData.client_name.toLowerCase();
  clientMatch = clientsData.find(client => {
    const fullName = `${client.first_name || ''} ${client.last_name || ''}`.toLowerCase();
    return fullName === clientNameLower;
  });
}

// Prepare client data
let clientData = {};
if (clientMatch) {
  clientData = {
    firstName: clientMatch.first_name || clientMatch.firstName || '',
    lastName: clientMatch.last_name || clientMatch.lastName || '',
    email: clientMatch.email || '',
    fullName: `${clientMatch.first_name || ''} ${clientMatch.last_name || ''}`.trim()
  };
} else {
  // Use data from reminder entry if client not found
  const nameParts = reminderData.client_name.split(' ');
  clientData = {
    firstName: nameParts[0] || 'Valued',
    lastName: nameParts.slice(1).join(' ') || 'Client',
    email: reminderData.client_email || '',
    fullName: reminderData.client_name || 'Valued Client'
  };
}

// Format session date
const sessionDate = new Date(reminderData.session_date);
const formattedDate = sessionDate.toLocaleDateString();

return {
  ...reminderData,
  ...clientData,
  sessionDate: formattedDate,
  trackingRow: reminderData.trackingRow
};
